    public function getComRecibidasJoinFacturaFondo($criteria = null, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $query = ComRecibidaQuery::create(null, $criteria);
        $query->joinWith('FacturaFondo', $join_behavior);

        return $this->getComRecibidas($query, $con);
    }

